1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.ConstraintViolation;
7	import jakarta.validation.Validator;
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a body that is missing (absent) or blank
15	 * (whitespace only) in any of firstName, lastName, address, city or telephone — {@code @Size(min = 1)}
16	 * on the DTO does not catch a whitespace-only value, so the check is explicit here. The remaining
17	 * schema constraints (pattern, max length) are validated too, so a bad value is still a 400.
18	 *
19	 * <p>Binds the body directly (no {@code @Valid}) so that a missing field surfaces as this rule's
20	 * {@code errors} response rather than the generic schema-validation escalation, and publishes the
21	 * body for {@link BuildOwner} to consume.
22	 */
23	public class ValidateOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Validator validator, Out<OwnerFieldsDto> validated)
26	            throws MissingOwnerFieldsException {
27	        List<String> errors = new ArrayList<>();
28	        normalizeAddress(request);
29	        addIfBlank(errors, "firstName", request.getFirstName());
30	        addIfBlank(errors, "lastName", request.getLastName());
31	        addIfBlank(errors, "address", request.getAddress());
32	        addIfBlank(errors, "city", request.getCity());
33	        normalizeTelephone(errors, request);
34	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
35	            String field = violation.getPropertyPath().toString();
36	            if (!field.isEmpty() && !errors.contains(field)) {
37	                errors.add(field);
38	            }
39	        }
40	        if (!errors.isEmpty()) {
41	            throw new MissingOwnerFieldsException(errors);
42	        }
43	        normalizeEmail(request);
44	        validated.set(request);
45	    }
46	
47	    /**
48	     * Email is optional. When absent nothing is done; when present the schema {@code @Email}
49	     * constraint (checked above) has already rejected a syntactically invalid address with a
50	     * {@code 400}, so a value reaching here is valid and is stored and returned lower-cased.
51	     */
52	    private static void normalizeEmail(OwnerFieldsDto request) {
53	        String email = request.getEmail();
54	        if (email != null) {
55	            request.setEmail(email.toLowerCase(java.util.Locale.ROOT));
56	        }
57	    }
58	
59	    /**
60	     * Canonically normalize the address (trim, collapse whitespace, upper-case, expand common
61	     * abbreviations) and write it back onto the request so it is stored and returned in normalized
62	     * form. Running before the blank check means an address that is whitespace-only — and so blank
63	     * after normalization — is rejected as an {@code address} required-field error (400).
64	     */
65	    private static void normalizeAddress(OwnerFieldsDto request) {
66	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
67	    }
68	
69	    private static void addIfBlank(List<String> errors, String name, String value) {
70	        if (value == null || value.isBlank()) {
71	            errors.add(name);
72	        }
73	    }
74	
75	    /**
76	     * Normalize the telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
77	     * '+' with country code is kept as-is; otherwise the number is assumed to be Australian ('+61')
78	     * and a single leading '0' is dropped from the national digits. The result must have 8 to 15
79	     * digits after the '+'. The E.164 value is written back onto the request so it is stored and
80	     * returned as {@code telephone}. Anything that cannot form a valid E.164 number is a
81	     * {@code telephone} error (400).
82	     */
83	    private static void normalizeTelephone(List<String> errors, OwnerFieldsDto request) {
84	        String e164 = toE164(request.getTelephone());
85	        if (e164 == null) {
86	            errors.add("telephone");
87	            return;
88	        }
89	        request.setTelephone(e164);
90	    }
91	
92	    /**
93	     * Convert a raw telephone into E.164 form, or return {@code null} when it cannot form a valid
94	     * E.164 number (fewer than 8 or more than 15 digits after the '+', or stray non-digit
95	     * characters remaining after the allowed separators are stripped).
96	     */
97	    static String toE164(String value) {
98	        if (value == null) {
99	            return null;
100	        }
101	        String cleaned = value.replaceAll("[\\s()-]", "");
102	        String digits;
103	        if (cleaned.startsWith("+")) {
104	            digits = cleaned.substring(1);
105	        }
106	        else {
107	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
108	            digits = "61" + national;
109	        }
110	        if (!digits.matches("[0-9]{8,15}")) {
111	            return null;
112	        }
113	        return "+" + digits;
114	    }
115	}
