3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	import net.officefloor.plugin.variable.Val;
9	
10	/**
11	 * Step of {@code POST /api/owners} that runs after {@link ValidateOwnerFields} has normalized the
12	 * telephone. Rejects the request when any existing owner already uses that normalized telephone,
13	 * so a duplicate is a 409 Conflict rather than a second owner sharing a phone number.
14	 */
15	public class RejectDuplicateTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = request.getTelephone();
20	        for (Owner existing : ownerRepository.findByTelephone(telephone)) {
21	            if (telephone.equals(existing.getTelephone())) {
22	                throw new DuplicateTelephoneException(telephone);
23	            }
24	        }
25	    }
26	}
