1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	import net.officefloor.plugin.variable.Val;
11	
12	/**
13	 * Step of {@code POST /api/owners} that runs after {@link ValidateOwnerFields} has published the
14	 * request body. Rejects the request when another owner already shares the same household — the same
15	 * last name and the same address, compared case-insensitively with collapsed whitespace — so a
16	 * duplicate household is a 409 Conflict rather than a second owner in the same home.
17	 *
18	 * <p>A request may opt in with {@code sharesHousehold: true} to deliberately register another owner
19	 * at an existing household; in that case the check is skipped and the create proceeds.
20	 */
21	public class RejectDuplicateHousehold {
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DuplicateHouseholdException {
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return;
27	        }
28	        String lastName = normalize(request.getLastName());
29	        String address = AddressNormalizer.normalize(request.getAddress());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (lastName.equals(normalize(existing.getLastName()))
32	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
33	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
34	            }
35	        }
36	    }
37	
38	    /** Lower-case, trim and collapse internal whitespace runs to a single space. */
39	    private static String normalize(String value) {
40	        if (value == null) {
41	            return "";
42	        }
43	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
44	    }
45	}
