1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Step of {@code POST /api/owners} that assigns the owner's {@code customerCode}, formatted
11	 * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters of
12	 * city, {@code LAST3} the upper-cased first three letters of lastName and {@code NNNN} is a
13	 * per-city 4-digit zero-padded sequence equal to one more than the number of owners already in
14	 * that city (e.g. {@code 'SYD-SMI-0007'}).
15	 *
16	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}; {@code @Val} yields the built
17	 * owner so the code is mutated in place and persisted by the save step. The sequence is counted
18	 * before this owner is saved, so successive creates in the same city receive consecutive numbers.
19	 */
20	public class AssignCustomerCode {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String city = owner.getCity();
24	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
25	        String lastName = owner.getLastName();
26	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
27	        int sequence = (int) ownerRepository.findAll().stream()
28	                .filter(o -> o.getCity() != null && o.getCity().equalsIgnoreCase(city))
29	                .count() + 1;
30	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
31	    }
32	}
