6	/**
7	 * Step of {@code POST /api/owners} that assigns the owner's {@code membershipNumber}, formatted
8	 * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
9	 * {@code registrationDate} year, zero-padded (e.g. {@code 'SYD-SMI-0007-M26'}).
10	 *
11	 * <p>Runs after {@link AssignCustomerCode} has set the {@code customerCode} and after
12	 * {@link BuildOwner} has set the {@code registrationDate}, and before {@link SaveOwner}. Derived
13	 * entirely from the owner's own fields, so it is seed-independent. {@code @Val} yields the built
14	 * owner so the number is mutated in place and persisted by the save step.
15	 */
16	public class AssignMembershipNumber {
17	
18	    public void service(@Val Owner owner) {
19	        int yy = Math.floorMod(owner.getRegistrationDate().getYear(), 100);
20	        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
21	    }
22	}
