1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	
15	/**
16	 * Step of {@code POST /api/owners} that runs after {@link BuildOwner} has produced the owner. When
17	 * the request opted in with {@code sharesHousehold: true} and an existing owner already occupies the
18	 * same household — the same last name and the same address, compared case-insensitively with
19	 * collapsed whitespace — this owner is joining that household. All members of a household share a
20	 * single stable {@code householdId}, derived deterministically from the normalized last name and
21	 * address so every member computes the same value regardless of the order they were created.
22	 *
23	 * <p>The shared id is assigned to the new owner and back-filled onto the existing member(s) that do
24	 * not yet carry it, so both sides of the join report the same {@code householdId}. When the request
25	 * does not opt in, or there is no existing household to join, no id is assigned (a lone owner has no
26	 * {@code householdId}). The duplicate-household rejection for non-opted-in requests has already run
27	 * in {@link RejectDuplicateHousehold}.
28	 */
29	public class AssignHousehold {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
32	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return;
34	        }
35	        String lastName = normalize(owner.getLastName());
36	        String address = AddressNormalizer.normalize(owner.getAddress());
37	        List<Owner> household = new ArrayList<>();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (lastName.equals(normalize(existing.getLastName()))
40	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
41	                household.add(existing);
42	            }
43	        }
44	        if (household.isEmpty()) {
45	            // No existing same-household owner: nothing to join, so no shared id.
46	            return;
47	        }
48	        String householdId = householdId(lastName, address);
49	        owner.setHouseholdId(householdId);
50	        for (Owner member : household) {
51	            if (member.getHouseholdId() == null) {
52	                member.setHouseholdId(householdId);
53	                ownerRepository.save(member);
54	            }
55	        }
56	    }
57	
58	    /** Lower-case, trim and collapse internal whitespace runs to a single space. */
59	    private static String normalize(String value) {
60	        if (value == null) {
61	            return "";
62	        }
63	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
64	    }
65	
66	    /**
67	     * Derive the stable household identifier {@code 'H-' + first 12 upper-case hex characters of
68	     * SHA-256(normalizedLastName + '\n' + normalizedAddress)}. Deterministic, so every owner in the
69	     * same household resolves to the same value.
70	     */
71	    private static String householdId(String lastName, String address) {
72	        try {
73	            byte[] digest = MessageDigest.getInstance("SHA-256")
74	                    .digest((lastName + "\n" + address).getBytes(StandardCharsets.UTF_8));
75	            StringBuilder sb = new StringBuilder();
76	            for (int i = 0; i < 6; i++) {
77	                sb.append(String.format("%02X", digest[i]));
78	            }
79	            return "H-" + sb;
80	        }
81	        catch (NoSuchAlgorithmException ex) {
82	            throw new IllegalStateException("SHA-256 not available", ex);
83	        }
84	    }
85	}
