1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Step of {@code POST /api/owners} that counts how many existing owners already share this owner's
11	 * {@code firstName} and {@code lastName} — compared case-insensitively — and stores the total on the
12	 * owner as {@code namesakeCount}.
13	 *
14	 * <p>Runs after {@link BuildOwner} so the owner carries its names, and before {@link SaveOwner} so
15	 * the count reflects only owners that existed before this create: the new owner is not yet persisted
16	 * and so is never counted among its own namesakes. {@code @Val} yields the built owner, mutated in
17	 * place and persisted by the save step.
18	 */
19	public class AssignNamesakeCount {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        String firstName = normalize(owner.getFirstName());
23	        String lastName = normalize(owner.getLastName());
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (firstName.equals(normalize(existing.getFirstName()))
27	                    && lastName.equals(normalize(existing.getLastName()))) {
28	                count++;
29	            }
30	        }
31	        owner.setNamesakeCount(count);
32	    }
33	
34	    /** Lower-case for a case-insensitive comparison; a null name normalizes to empty. */
35	    private static String normalize(String value) {
36	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
37	    }
38	}
