1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Canonical normalization for an owner's postal {@code address}, applied whenever an owner is
7	 * created. The address is trimmed, its internal whitespace runs are collapsed to a single space,
8	 * it is upper-cased, and common street-type abbreviations are expanded on a whole-token basis
9	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
10	 *
11	 * <p>The normalized value is what gets stored and returned, and it is the form every comparison of
12	 * addresses uses — the required-field blank check, household-duplicate detection and the shared
13	 * household id. Normalization is idempotent, so re-normalizing an already-normalized address is a
14	 * no-op. A {@code null} or whitespace-only address normalizes to the empty string.
15	 */
16	final class AddressNormalizer {
17	
18	    private AddressNormalizer() {
19	    }
20	
21	    static String normalize(String value) {
22	        if (value == null) {
23	            return "";
24	        }
25	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
26	        if (collapsed.isEmpty()) {
27	            return "";
28	        }
29	        String[] tokens = collapsed.split(" ");
30	        StringBuilder sb = new StringBuilder(collapsed.length());
31	        for (int i = 0; i < tokens.length; i++) {
32	            if (i > 0) {
33	                sb.append(' ');
34	            }
35	            sb.append(expand(tokens[i]));
36	        }
37	        return sb.toString();
38	    }
39	
40	    private static String expand(String token) {
41	        switch (token) {
42	            case "ST":
43	                return "STREET";
44	            case "RD":
45	                return "ROAD";
46	            case "AVE":
47	                return "AVENUE";
48	            default:
49	                return token;
50	        }
51	    }
52	}
